=<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>n8n-notes</title>
<style>
  :root {
    --canvas: #faf9f6;
    --ink: #1f2430;
    --muted: #8a8f98;
    --line: #e7e5df;
    --accent: #2fa36b;
    --accent-ink: #ffffff;
    --card-shadow: 0 1px 2px rgba(31,36,48,.04), 0 6px 20px rgba(31,36,48,.06);
    --radius: 14px;
    --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
    --sans: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  }
  * { box-sizing: border-box; }
  html, body { margin: 0; }
  body {
    background: var(--canvas);
    color: var(--ink);
    font-family: var(--sans);
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
    padding: 32px 20px 80px;
  }
  .wrap { max-width: 940px; margin: 0 auto; }

  header {
    display: flex; align-items: baseline; justify-content: space-between; gap: 16px;
    padding-bottom: 16px; margin-bottom: 18px; border-bottom: 1px solid var(--line);
  }
  h1 { font-size: 27px; font-weight: 680; letter-spacing: -.02em; margin: 0; white-space: nowrap; }
  h1 .dot { color: var(--accent); }
  .h1ai { display: inline-flex; align-items: center; margin-left: 8px; color: var(--accent); vertical-align: middle; }
  .h1ai svg { width: 18px; height: 18px; }
  .h1ai.off { display: none; }
  .count { font-family: var(--mono); font-size: 12.5px; color: var(--muted); letter-spacing: .02em; white-space: nowrap; }

  .search {
    flex: 1; max-width: 320px; margin-left: auto;
    border: 1px solid var(--line); border-radius: 9px; background: #fff;
    display: flex; align-items: center; gap: 8px; padding: 7px 11px;
  }
  .search svg { flex: none; color: var(--muted); }
  .search input {
    border: 0; outline: 0; background: transparent; width: 100%;
    font-family: var(--sans); font-size: 13.5px; color: var(--ink);
  }
  .search input::placeholder { color: var(--muted); }

  .compose {
    border: 1px solid var(--line); border-radius: var(--radius);
    background: #fff; padding: 16px 16px 14px; margin-bottom: 24px;
  }
  .compose input.title, .compose textarea {
    width: 100%; border: 0; outline: 0; background: transparent;
    font-family: var(--sans); color: var(--ink); resize: none;
  }
  .compose input.title { font-size: 17px; font-weight: 620; letter-spacing: -.01em; padding: 2px 0; }
  .compose input.title::placeholder { color: var(--muted); }
  .compose textarea { font-size: 14.5px; padding: 6px 0 2px; min-height: 44px; }
  .compose textarea::placeholder { color: var(--muted); }
  .compose .bar {
    display: flex; align-items: center; justify-content: space-between;
    margin-top: 10px; padding-top: 12px; border-top: 1px solid var(--line);
  }
  .swatches { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
  .swatch {
    width: 20px; height: 20px; border-radius: 50%; cursor: pointer;
    border: 2px solid rgba(31,36,48,.08); padding: 0; transition: transform .12s ease;
  }
  .swatch[aria-pressed="true"] { border-color: var(--ink); transform: scale(1.12); }
  .ai-swatch { display: grid; place-items: center; background: #fff !important; color: var(--muted); }
  .ai-swatch svg { width: 12px; height: 12px; }
  .ai-swatch[aria-pressed="true"] { color: var(--accent); }
  button { font-family: var(--sans); cursor: pointer; border: 0; }
  .add {
    background: var(--accent); color: var(--accent-ink);
    font-size: 14px; font-weight: 600; padding: 8px 16px; border-radius: 9px;
    letter-spacing: -.01em; transition: filter .12s ease, transform .06s ease;
  }
  .add:hover { filter: brightness(1.05); }
  .add:active { transform: translateY(1px); }
  .add:disabled { opacity: .45; cursor: not-allowed; }

  .controls { display: flex; gap: 18px; align-items: center; flex-wrap: wrap; margin: -6px 0 20px; }
  .ctl { display: inline-flex; align-items: center; gap: 7px; font-family: var(--mono); font-size: 12px; color: var(--muted); }
  .ctl select { font-family: var(--sans); font-size: 13px; color: var(--ink); background: #fff;
                border: 1px solid var(--line); border-radius: 8px; padding: 5px 8px; cursor: pointer; outline: none; }
  .ctl select:hover { border-color: rgba(31,36,48,.28); }
  .grid {
    display: grid; gap: 16px;
    grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
    align-items: stretch;
  }
  .card {
    position: relative;
    border-radius: var(--radius); padding: 15px 16px 12px;
    box-shadow: var(--card-shadow);
    border: 1px solid rgba(31,36,48,.05);
    display: flex; flex-direction: column; min-height: 96px;
  }
  .card[draggable="true"] { cursor: grab; }
  .card.dragging { cursor: grabbing; opacity: .55; box-shadow: none;
                   outline: 2px dashed rgba(31,36,48,.28); outline-offset: -2px; }
  .card.dragging * { visibility: hidden; }  /* show just the empty slot while dragging */
  .card.hidden-card { display: none !important; }
  .card h3 { margin: 0 0 6px; font-size: 15.5px; font-weight: 660; letter-spacing: -.01em; word-break: break-word; }
  .card p { margin: 0; font-size: 14px; white-space: pre-wrap; word-break: break-word; color: #2c313c; flex: 1; }
  .card .meta {
    display: flex; align-items: center; justify-content: space-between;
    margin-top: 12px; padding-top: 10px; border-top: 1px solid rgba(31,36,48,.08);
    font-family: var(--mono); font-size: 11px; color: rgba(31,36,48,.5);
  }
  .card .acts { display: flex; gap: 4px; opacity: 0; transition: opacity .14s ease; }
  .card:hover .acts, .card:focus-within .acts { opacity: 1; }
  .icon {
    background: rgba(31,36,48,.06); color: rgba(31,36,48,.7);
    font-size: 11px; font-weight: 600; padding: 3px 8px; border-radius: 6px; font-family: var(--mono);
  }
  .icon:hover { background: rgba(31,36,48,.12); }
  .icon.danger:hover { background: #ffdad1; color: #b23a1e; }

  .card.editing { align-self: start; }
  .card.editing input.e-title, .card.editing textarea.e-body {
    width: 100%; border: 0; outline: 0; background: rgba(255,255,255,.55);
    border-radius: 7px; padding: 6px 8px; font-family: var(--sans); color: var(--ink);
    margin-bottom: 8px; resize: vertical;
  }
  .card.editing input.e-title { font-size: 15px; font-weight: 640; }
  .card.editing textarea.e-body { font-size: 14px; min-height: 60px; }
  .card.editing .edit-bar { display: flex; flex-direction: column; align-items: stretch; gap: 10px; }
  .card.editing .edit-bar .acts { display: flex; justify-content: flex-end; gap: 8px; opacity: 1; }
  .save { background: var(--accent); color: #fff; font-size: 11px; font-weight: 600; padding: 4px 12px; border-radius: 6px; font-family: var(--mono); }

  /* AI title transition */
  .card h3.ai-shimmer {
    color: transparent;
    background: linear-gradient(90deg, rgba(31,36,48,.30) 20%, var(--accent) 50%, rgba(31,36,48,.30) 80%);
    background-size: 200% 100%;
    -webkit-background-clip: text; background-clip: text;
    animation: aishimmer 1.05s linear infinite;
  }
  @keyframes aishimmer { to { background-position: -200% 0; } }
  .card h3.ai-typing::after {
    content: "▌"; color: var(--accent); margin-left: 1px; font-weight: 400;
    animation: aicaret .7s steps(1) infinite;
  }
  @keyframes aicaret { 50% { opacity: 0; } }
  .compose input.title.gen-loading {
    background: linear-gradient(90deg, rgba(31,36,48,.06) 20%, rgba(47,163,107,.20) 50%, rgba(31,36,48,.06) 80%);
    background-size: 200% 100%; border-radius: 6px;
    animation: aishimmer 1.05s linear infinite;
  }

  .empty {
    text-align: center; color: var(--muted); font-size: 14.5px;
    padding: 46px 0; border: 1px dashed var(--line); border-radius: var(--radius);
  }
  .foot { margin-top: 28px; padding-top: 16px; border-top: 1px solid var(--line);
          display: flex; align-items: center; justify-content: center; gap: 7px;
          font-family: var(--mono); font-size: 12px; color: var(--muted); }
  .foot .dotstat { width: 8px; height: 8px; border-radius: 50%; background: var(--accent); }
  .foot.off .dotstat { background: var(--muted); }
  .toast {
    position: fixed; left: 50%; bottom: 26px; transform: translateX(-50%) translateY(20px);
    background: var(--ink); color: #fff; font-size: 13px; padding: 9px 16px; border-radius: 9px;
    opacity: 0; pointer-events: none; transition: opacity .2s ease, transform .2s ease; font-family: var(--mono);
  }
  .toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }
  .toast-action { margin-left: 14px; background: transparent; border: 0; color: #6ee7b7; pointer-events: auto;
                  font-family: var(--mono); font-size: 13px; font-weight: 700; cursor: pointer; padding: 0; }
  .toast-action:hover { text-decoration: underline; }

  .seg { display: inline-flex; background: rgba(31,36,48,.06); border-radius: 999px; padding: 3px; gap: 2px;
         font-family: var(--mono); font-size: 11px; }
  .seg-btn { border: 0; background: transparent; color: var(--muted); padding: 4px 11px; border-radius: 999px; cursor: pointer; }
  .seg-btn[aria-pressed="true"] { background: #fff; color: var(--ink); box-shadow: 0 1px 2px rgba(0,0,0,.08); }

  @media (prefers-reduced-motion: reduce) { * { animation: none !important; transition: none !important; } }
</style>
</head>
<body>
  <div class="wrap">
    <header>
      <h1>n8n<span class="dot">-</span>notes<span class="h1ai" id="h1ai" title="AI-powered"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 3l1.3 3.4L13.7 7.7 10.3 9 9 12.4 7.7 9 4.3 7.7 7.7 6.4z"/><path d="M17 12l.8 2 2 .8-2 .8-.8 2-.8-2-2-.8 2-.8z"/></svg></span></h1>
      <div class="search">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><circle cx="11" cy="11" r="7"></circle><line x1="21" y1="21" x2="16.65" y2="16.65"></line></svg>
        <input id="q" type="search" placeholder="Search notes" autocomplete="off" />
      </div>
      <div class="seg" id="searchToggle">
        <button type="button" class="seg-btn" data-mode="local" aria-pressed="true">Local</button>
        <button type="button" class="seg-btn" data-mode="semantic" aria-pressed="false">Semantic</button>
      </div>
      <span class="count" id="count">—</span>
    </header>

    <div class="compose">
      <input class="title" id="c-title" placeholder="Title — added by AI, or type your own" maxlength="120" />
      <textarea id="c-body" placeholder="Write a note…" rows="3"></textarea>
      <div class="bar">
        <div class="swatches" id="c-swatches"></div>
        <button class="add" id="c-add">Add note</button>
      </div>
    </div>

    <div class="controls">
      <label class="ctl">Sort
        <select id="sortSel">
          <option value="manual">Manual</option>
          <option value="newest">Newest</option>
          <option value="oldest">Oldest</option>
        </select>
      </label>
      <label class="ctl">Category
        <select id="catSel"></select>
      </label>
    </div>

    <div class="grid" id="grid"></div>
    <div class="empty" id="empty" style="display:none">No notes yet. Write your first one above.</div>
    <footer class="foot" id="foot"></footer>
  </div>
  <div class="toast" id="toast"></div>

<script>
  // ─── CONFIG ────────────────────────────────────────────────
  // Turn all AI features on/off (auto-title, auto-colour, smart search).
  const AI_ENABLED = {{ $json.aiEnabled ? 'true' : 'false' }};
  // ───────────────────────────────────────────────────────────

  const IS_MAC = /Mac|iPhone|iPad|iPod/.test(navigator.platform || navigator.userAgent || "");
  const MOD = IS_MAC ? "⌘" : "Ctrl";

  // Each operation has its own webhook. Resolve them relative to where this
  // page is served (works for both /webhook/notes and /webhook-test/notes).
  const BASE = location.pathname.replace(/notes\/?$/, "");
  const EP = {
    list:   { url: BASE + "notes-list",   method: "GET"    },
    create: { url: BASE + "notes-create", method: "POST"   },
    update: { url: BASE + "notes-update", method: "PUT"    },
    delete: { url: BASE + "notes-delete", method: "DELETE" },
    title:  { url: BASE + "notes-title",  method: "POST" },
    search: { url: BASE + "notes-search", method: "POST" },
  };

  // Category -> tint. The LLM classifies each note; edit mode can override.
  const TINTS = {
    work:"#dbe4ff", ideas:"#ece0ff", travel:"#cdeefb", health:"#d3f0e6",
    finance:"#cdeacc", shopping:"#fff3c4", personal:"#ffe9cf", family:"#ffe0ec",
    urgent:"#ffd6d9", other:"#e8e8ee",
    // legacy colour names still render
    butter:"#fff3c4", sage:"#ddf0dc", sky:"#d9e8ff", blush:"#ffe0ec", lilac:"#ece0ff",
  };
  const ORDER = ["work","personal","shopping","health","finance","ideas","urgent","travel","family","other"];
  const DEFAULT_CAT = "other";

  let ALL = [];             // full note list, sorted by position asc
  let term = "";            // active search term
  let smartIds = null;      // array of ids when AI search is active, else null
  let searchMode = "local"; // "local" (substring) | "semantic" (AI)
  let compose = "auto";     // compose colour: a category key, or 'auto' (AI picks)
  let sortMode = "manual";  // manual (position) | newest | oldest
  let catFilter = "all";    // "all" or a category key
  let dragId = null;
  const AI_SVG = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 3l1.3 3.4L13.7 7.7 10.3 9 9 12.4 7.7 9 4.3 7.7 7.7 6.4z"/><path d="M17 12l.8 2 2 .8-2 .8-.8 2-.8-2-2-.8 2-.8z"/></svg>';
  const elmap = new Map();  // id -> { el, key } : cards persist across renders

  const $ = (id) => document.getElementById(id);
  const grid = $("grid"), empty = $("empty"), countEl = $("count");

  function toast(msg, action) {
    const t = $("toast");
    t.innerHTML = "";
    t.appendChild(document.createTextNode(msg));
    if (action) {
      const b = document.createElement("button");
      b.className = "toast-action"; b.type = "button"; b.textContent = action.label;
      b.onclick = () => { t.classList.remove("show"); clearTimeout(t._h); action.fn(); };
      t.appendChild(b);
    }
    t.classList.add("show");
    clearTimeout(t._h);
    t._h = setTimeout(() => t.classList.remove("show"), action ? 6000 : 1600);
  }
  function when(iso) {
    const d = new Date(iso);
    if (isNaN(d)) return "";
    return d.toLocaleDateString(undefined, { month: "short", day: "numeric" })
      + " · " + d.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" });
  }
  function esc(s) { const p = document.createElement("p"); p.textContent = s == null ? "" : s; return p.innerHTML; }

  async function call(op, payload) {
    const { url, method } = EP[op];
    const opts = { method };
    if (method !== "GET") { opts.headers = { "Content-Type": "application/json" }; opts.body = JSON.stringify(payload || {}); }
    const res = await fetch(url, opts);
    if (!res.ok) throw new Error("Request failed (" + res.status + ")");
    const text = await res.text();
    if (!text) return null;                 // e.g. delete returns an empty body
    try { return JSON.parse(text); } catch (_) { return text; }
  }

  // Updates rewrite every column, so always send the full record merged with
  // the change — a colour/position-only edit can't blank other fields.
  async function saveNote(id, changes) {
    const n = ALL.find((x) => String(x.id) === String(id));
    if (!n) return;
    await call("update", { id, title: n.title, body: n.body, color: n.color, position: n.position, ...changes });
    Object.assign(n, changes);
  }

  function swatchRow(selected, onPick) {
    const box = document.createElement("div");
    box.className = "swatches";
    ORDER.forEach((name) => {
      const b = document.createElement("button");
      b.className = "swatch"; b.type = "button"; b.style.background = TINTS[name]; b.title = name;
      b.setAttribute("aria-pressed", String(name === selected));
      b.onclick = () => {
        [...box.children].forEach((c) => c.setAttribute("aria-pressed", String(c.title === name)));
        onPick(name);
      };
      box.appendChild(b);
    });
    return box;
  }

  const matches = (n, t) =>
    String(n.title || "").toLowerCase().includes(t) ||
    String(n.body || "").toLowerCase().includes(t);
  const cardKey = (n) => [n.id, n.title, n.body, n.color].join("\u0001");
  const ts = (n) => Date.parse(n.createdAt || n.updatedAt || 0) || 0;
  function sortView() {
    if (sortMode === "newest") ALL.sort((a, b) => ts(b) - ts(a));
    else if (sortMode === "oldest") ALL.sort((a, b) => ts(a) - ts(b));
    else ALL.sort((a, b) => a.position - b.position);
  }
  const sortByPosition = () => ALL.sort((a, b) => a.position - b.position);

  // ── Ordering helpers (positions are contiguous integers from 0) ─────────
  async function persist(notes) {
    await Promise.all(notes.map((n) => saveNote(n.id, { position: n.position })));
  }
  // Re-sequence every note to 0..n-1 in position order, persist changes.
  async function reindex() {
    sortByPosition();
    const changed = [];
    ALL.forEach((n, i) => { if (n.position !== i) { n.position = i; changed.push(n); } });
    render();
    if (changed.length) { try { await persist(changed); } catch (e) { toast(e.message); } }
  }

  // ── Card element (built once, reused; content refreshed only when changed) ─
  function buildCard(n) {
    const el = document.createElement("article");
    el.className = "card";
    el.dataset.id = n.id;
    el.addEventListener("dragstart", () => { if (!el.draggable) return; dragId = n.id; el.classList.add("dragging"); });
    el.addEventListener("dragend", onDrop);
    fillCard(el, n);
    return el;
  }

  function fillCard(el, n) {
    el.classList.remove("editing");
    el.style.background = TINTS[n.color] || TINTS.butter;
    el.innerHTML =
      '<h3>' + (esc(n.title) || "Untitled") + '</h3>' +
      '<p>' + esc(n.body) + '</p>' +
      '<div class="meta"><span>' + when(n.updatedAt || n.createdAt) + '</span>' +
      '<span class="acts">' +
        '<button class="icon" data-act="edit">edit</button>' +
        '<button class="icon danger" data-act="del">delete</button>' +
      '</span></div>';
    el.querySelector('[data-act="edit"]').onclick = () => enterEdit(el, n);
    el.querySelector('[data-act="del"]').onclick = async () => {
      const snapshot = { title: n.title, body: n.body, color: n.color, position: n.position };
      el.style.opacity = ".4";
      try {
        await call("delete", { id: n.id });
        await load();
        toast("Note deleted", { label: "Undo", fn: () => undoDelete(snapshot) });
      } catch (e) { el.style.opacity = "1"; toast(e.message); }
    };
    el.ondblclick = (e) => {
      if (e.target.closest("button")) return;          // ignore edit/delete buttons
      if (el.classList.contains("editing")) return;
      enterEdit(el, n);
    };
  }

  function enterEdit(el, n) {
    el.draggable = false;
    el.classList.add("editing");
    let color = n.color || "butter";
    el.innerHTML =
      '<input class="e-title" maxlength="120" />' +
      '<textarea class="e-body" rows="3"></textarea>' +
      '<div class="meta"><div class="edit-bar" style="width:100%">' +
        '<span class="e-swatches"></span>' +
        '<span class="acts" style="opacity:1">' +
          '<button class="icon" data-act="cancel">cancel</button>' +
          '<button class="save" data-act="save">save</button>' +
        '</span>' +
      '</div></div>';
    const t = el.querySelector(".e-title"), b = el.querySelector(".e-body");
    t.value = n.title || ""; b.value = n.body || "";
    const autoGrow = () => { b.style.height = "auto"; b.style.height = Math.max(60, b.scrollHeight) + "px"; };
    autoGrow();                              // match the note's current body height
    b.addEventListener("input", autoGrow);   // and grow as you type
    el.querySelector(".e-swatches").appendChild(swatchRow(color, (c) => { color = c; el.style.background = TINTS[c]; }));
    t.focus();

    const teardown = () => { document.removeEventListener("keydown", onKey); document.removeEventListener("mousedown", onOut); };
    const cancel = () => { teardown(); fillCard(el, ALL.find((x) => String(x.id) === String(n.id)) || n); el.draggable = !term.trim(); };
    const onKey = (e) => { if (e.key === "Escape") { e.preventDefault(); cancel(); } };
    const onOut = (e) => { if (!el.contains(e.target)) cancel(); };
    document.addEventListener("keydown", onKey);
    setTimeout(() => document.addEventListener("mousedown", onOut), 0);  // ignore the click that opened edit

    el.querySelector('[data-act="cancel"]').onclick = cancel;
    el.querySelector('[data-act="save"]').title = "Save (" + MOD + " + S)";
    el.querySelector('[data-act="save"]').onclick = async () => {
      teardown();
      const typed = t.value.trim(), newBody = b.value, newColor = color;
      const bodyChanged = newBody.trim() !== String(n.body || "").trim();
      try {
        if (!bodyChanged || !AI_ENABLED) {
          await saveNote(n.id, { title: typed, body: newBody, color: newColor });
          fillCard(el, ALL.find((x) => String(x.id) === String(n.id)) || n);
          el.draggable = !term.trim();
          toast("Saved");
          return;
        }
        // Body changed -> persist body/colour, then regenerate title + category with AI.
        await saveNote(n.id, { title: typed || n.title, body: newBody, color: newColor });
        fillCard(el, ALL.find((x) => String(x.id) === String(n.id)) || n);
        el.draggable = !term.trim();
        const h3 = el.querySelector("h3");
        if (h3) h3.classList.add("ai-shimmer");
        let gen = { title: "", category: newColor };
        try { gen = await fetchTitle(newBody); } catch (_) { /* fall back below */ }
        const title = gen.title || newBody.split(/\s+/).slice(0, 6).join(" ");
        const cat = gen.category || DEFAULT_CAT;
        if (h3) h3.classList.remove("ai-shimmer");
        el.style.transition = "background-color .35s ease";
        el.style.background = TINTS[cat] || TINTS[DEFAULT_CAT];   // recolour by category
        await saveNote(n.id, { title, color: cat });
        if (h3) await typeInto(h3, title);
        render();                      // keep card cache in sync with new title/colour
        toast("Updated by AI");
      } catch (e) { toast(e.message); }
    };
  }

  // ── Reconcile: keep nodes alive, only create/move/remove ────────────────
  function reconcile() {
    const ids = new Set(ALL.map((n) => String(n.id)));
    for (const [id, rec] of [...elmap]) if (!ids.has(id)) { rec.el.remove(); elmap.delete(id); }
    ALL.forEach((n, i) => {
      const id = String(n.id);
      let rec = elmap.get(id);
      if (!rec) {
        const el = buildCard(n);
        rec = { el, key: cardKey(n) };
        elmap.set(id, rec);
        if (el.animate) el.animate(
          [{ opacity: 0, transform: "translateY(6px)" }, { opacity: 1, transform: "none" }],
          { duration: 200, easing: "ease" });
      } else if (rec.key !== cardKey(n) && !rec.el.classList.contains("editing")) {
        fillCard(rec.el, n); rec.key = cardKey(n);
      }
      const ref = grid.children[i];
      if (ref !== rec.el) grid.insertBefore(rec.el, ref || null);
    });
  }

  function applyFilter() {
    const t = term.trim().toLowerCase();
    const smart = Array.isArray(smartIds);
    const localFilter = !smart && searchMode === "local" && !!t;
    const canDrag = sortMode === "manual" && catFilter === "all" && !smart && !localFilter;
    let vis = 0;
    for (const n of ALL) {
      const rec = elmap.get(String(n.id));
      if (!rec) continue;
      const catOk = catFilter === "all" || (n.color || DEFAULT_CAT) === catFilter;
      const searchOk = smart ? smartIds.includes(String(n.id)) : (localFilter ? matches(n, t) : true);
      const show = catOk && searchOk;
      rec.el.classList.toggle("hidden-card", !show);
      rec.el.draggable = canDrag;
      if (show) vis++;
    }
    const filtered = smart || localFilter || catFilter !== "all";
    countEl.textContent = (smart ? "AI · " : "") + (filtered ? vis + " / " + ALL.length
                          : ALL.length + (ALL.length === 1 ? " note" : " notes"));
    empty.style.display = vis === 0 ? "block" : "none";
    empty.textContent = filtered ? "No notes match." : "No notes yet. Write your first one above.";
  }

  function buildControls() {
    const catSel = $("catSel");
    catSel.innerHTML = '<option value="all">All</option>' +
      ORDER.map((c) => '<option value="' + c + '">' + c.charAt(0).toUpperCase() + c.slice(1) + '</option>').join('');
    $("sortSel").value = sortMode; catSel.value = catFilter;
    $("sortSel").addEventListener("change", (e) => { sortMode = e.target.value; render(); });
    catSel.addEventListener("change", (e) => { catFilter = e.target.value; render(); });
  }

  function buildComposePalette() {
    const box = $("c-swatches");
    box.innerHTML = "";
    const select = (val) => {
      compose = val;
      [...box.children].forEach((c) => c.setAttribute("aria-pressed", String(c.dataset.val === val)));
    };
    if (AI_ENABLED) {
      const ai = document.createElement("button");
      ai.className = "swatch ai-swatch"; ai.type = "button"; ai.dataset.val = "auto";
      ai.title = "Let AI pick the colour"; ai.innerHTML = AI_SVG;
      ai.setAttribute("aria-pressed", "true");
      ai.onclick = () => select("auto");
      box.appendChild(ai);
    }
    ORDER.forEach((cat) => {
      const b = document.createElement("button");
      b.className = "swatch"; b.type = "button"; b.dataset.val = cat;
      b.style.background = TINTS[cat]; b.title = cat;
      b.setAttribute("aria-pressed", String(!AI_ENABLED && cat === DEFAULT_CAT));
      b.onclick = () => select(cat);
      box.appendChild(b);
    });
    compose = AI_ENABLED ? "auto" : DEFAULT_CAT;
  }

  function render() { sortView(); reconcile(); applyFilter(); }

  // ── Drag reordering ─────────────────────────────────────────────────────
  // Which card should the dragged one sit *before*? Walk the cards in visual
  // (reading) order and pick the first one the pointer is ahead of: on a lower
  // row, or same row and left of its centre. null => drop at the end.
  function dropBeforeEl(x, y) {
    const cards = [...grid.querySelectorAll(".card:not(.dragging):not(.hidden-card)")];
    for (const el of cards) {
      const b = el.getBoundingClientRect();
      if (y < b.top) return el;                        // pointer is on a row above this card
      if (y <= b.bottom && x < b.left + b.width / 2) return el; // same row, left of centre
    }
    return null;
  }

  // FLIP: animate the cards that shift so they glide instead of snapping.
  function flipMove(mutate) {
    const cards = [...grid.querySelectorAll(".card:not(.hidden-card)")];
    const first = new Map();
    cards.forEach((el) => first.set(el, el.getBoundingClientRect()));
    mutate();
    cards.forEach((el) => {
      if (el.classList.contains("dragging")) return;   // the dragged card follows the cursor
      const f = first.get(el); if (!f) return;
      const l = el.getBoundingClientRect();
      const dx = f.left - l.left, dy = f.top - l.top;
      if (!dx && !dy) return;
      el.style.transition = "none";
      el.style.transform = "translate(" + dx + "px," + dy + "px)";
      requestAnimationFrame(() => {
        el.style.transition = "transform .18s cubic-bezier(.2,.7,.3,1)";
        el.style.transform = "";
      });
    });
  }

  function clearFlip() {
    grid.querySelectorAll(".card").forEach((el) => { el.style.transition = ""; el.style.transform = ""; });
  }

  grid.addEventListener("dragover", (e) => {
    if (dragId == null) return;
    e.preventDefault();
    const dragging = grid.querySelector(".dragging");
    if (!dragging) return;
    const ref = dropBeforeEl(e.clientX, e.clientY);
    if (ref === dragging) return;
    // already in the right slot? (its current next sibling is the target)
    if (dragging.nextElementSibling === ref) return;
    flipMove(() => grid.insertBefore(dragging, ref));
  });

  async function onDrop() {
    const dragging = grid.querySelector(".dragging");
    if (dragging) dragging.classList.remove("dragging");
    clearFlip();
    const id = dragId; dragId = null;
    if (id == null) return;

    // New visual order -> positions 0..n-1.
    const ids = [...grid.querySelectorAll(".card:not(.hidden-card)")].map((el) => el.dataset.id);
    const changed = [];
    ids.forEach((cid, i) => {
      const n = ALL.find((x) => String(x.id) === String(cid));
      if (n && n.position !== i) { n.position = i; changed.push(n); }
    });
    render();
    if (changed.length) { try { await persist(changed); } catch (e) { toast(e.message); } }
  }

  // ── Create (prepends: position 0, everything else shifts down) ──────────
  async function undoDelete(s) {
    try {
      await call("create", { title: s.title, body: s.body, color: s.color, position: s.position });
      await load(); await reindex();
      toast("Note restored");
    } catch (e) { toast(e.message); }
  }

  async function add() {
    const body = $("c-body").value.trim();
    if (!body) { toast("Write a note first"); return; }
    const titleEl = $("c-title");
    const typed = titleEl.value.trim();
    const auto = AI_ENABLED && compose === "auto";
    const wantLLM = AI_ENABLED && (!typed || auto);
    const btn = $("c-add"); const label = btn.textContent;
    btn.disabled = true;
    try {
      let gen = { title: "", category: DEFAULT_CAT };
      if (wantLLM) {                                 // call the LLM only when needed
        btn.textContent = "Generating…";
        if (!typed) { titleEl.disabled = true; titleEl.classList.add("gen-loading"); }
        try { gen = await fetchTitle(body); } catch (_) { /* fall back below */ }
      }
      const title = typed || gen.title || body.split(/\s+/).slice(0, 6).join(" ");
      const color = auto ? (gen.category || DEFAULT_CAT) : compose;
      if (wantLLM && !typed) { titleEl.classList.remove("gen-loading"); titleEl.disabled = false; await typeIntoInput(titleEl, title); }
      btn.textContent = "Adding…";
      await call("create", { title, body, color, position: -1 });
      titleEl.value = ""; $("c-body").value = "";
      await load(); await reindex();
      toast("Note added");
    } catch (e) { toast(e.message); }
    finally { btn.disabled = false; btn.textContent = label; $("c-body").focus(); }
  }

  async function smartSearch(q) {
    if (!q) { smartIds = null; render(); return; }
    countEl.textContent = "Searching…";
    try {
      const notes = ALL.map((n) => ({ id: n.id, title: n.title, body: n.body }));
      const res = await fetch(EP.search.url, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ query: q, notes }),
      });
      if (!res.ok) throw new Error("search http " + res.status);
      const out = await res.json();
      let ids = out.ids ?? out;
      if (typeof ids === "string") { const m = ids.match(/\[[\s\S]*\]/); ids = m ? JSON.parse(m[0]) : []; }
      if (!Array.isArray(ids)) ids = [];
      smartIds = ids.map(String);
      render();
    } catch (e) { toast(e.message); smartIds = null; render(); }
  }

  // ── Title generation (Groq LLM) ────────────────────────────────────────
  async function fetchTitle(body) {
    const res = await fetch(EP.title.url, {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ body }),
    });
    if (!res.ok) throw new Error("title http " + res.status);
    const out = await res.json();
    const content = String(out.content ?? out.title ?? out.choices?.[0]?.message?.content ?? "");
    let title = "", category = DEFAULT_CAT;
    try {
      const m = content.match(/\{[\s\S]*\}/);
      const obj = JSON.parse(m ? m[0] : content);
      title = String(obj.title || "").trim();
      category = String(obj.category || DEFAULT_CAT).trim().toLowerCase();
    } catch (_) {
      title = content.trim().replace(/^["']|["']$/g, "");
    }
    if (!TINTS[category]) category = DEFAULT_CAT;
    return { title, category };
  }

  // Type text into an h3 with a blinking caret (respects reduced motion).
  function typeInto(h3, text) {
    return new Promise((resolve) => {
      if (matchMedia("(prefers-reduced-motion: reduce)").matches) { h3.textContent = text; return resolve(); }
      const chars = Array.from(text);
      h3.textContent = "";
      h3.classList.add("ai-typing");
      let i = 0;
      const tick = () => {
        h3.textContent = chars.slice(0, i).join("");
        if (i < chars.length) { i++; setTimeout(tick, 24); }
        else { h3.classList.remove("ai-typing"); resolve(); }
      };
      tick();
    });
  }

  function typeIntoInput(input, text) {
    return new Promise((resolve) => {
      if (matchMedia("(prefers-reduced-motion: reduce)").matches) { input.value = text; return resolve(); }
      const chars = Array.from(text);
      input.value = ""; try { input.focus(); } catch (_) {}
      let i = 0;
      const tick = () => {
        input.value = chars.slice(0, i).join("");
        if (i < chars.length) { i++; setTimeout(tick, 24); } else resolve();
      };
      tick();
    });
  }

  async function load() {
    try {
      const out = await call("list");
      let notes = Array.isArray(out) ? out : (out.notes || out.data || []);
      notes.forEach((n) => {
        const p = n.position;
        n.position = (p !== undefined && p !== null && p !== "") ? Number(p) : 0;
      });
      ALL = notes;
      render();
    } catch (e) {
      ALL = [];
      for (const [, rec] of elmap) rec.el.remove();
      elmap.clear();
      empty.style.display = "block";
      empty.textContent = "Couldn't reach the notes API. Is the workflow active?";
      countEl.textContent = "—";
    }
  }

  buildComposePalette();
  buildControls();

  const q = $("q");
  function setSearchMode(mode) {
    searchMode = mode;
    [...$("searchToggle").children].forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.mode === mode)));
    q.placeholder = mode === "semantic" ? "Describe what you're after, then ↵" : "Search notes";
    if (mode === "local") { smartIds = null; render(); }
    else if (term.trim()) { smartSearch(term.trim()); }
  }
  [...$("searchToggle").children].forEach((b) => { b.onclick = () => setSearchMode(b.dataset.mode); });

  if (!AI_ENABLED) {
    document.getElementById("h1ai").classList.add("off");
    $("searchToggle").style.display = "none";   // no semantic search without AI
    $("c-title").placeholder = "Title";
    searchMode = "local";
  }

  $("c-add").onclick = add;
  $("c-add").title = "Add note (" + MOD + " + Enter)";
  q.title = "Search (" + MOD + " + K)";
  q.addEventListener("input", (e) => {
    term = e.target.value;
    if (searchMode === "local") { smartIds = null; render(); }   // live substring
    else if (!term.trim()) { smartIds = null; render(); }         // cleared -> show all
  });
  q.addEventListener("keydown", (e) => {
    if (e.key === "Enter" && !e.metaKey && !e.ctrlKey && AI_ENABLED && searchMode === "semantic") {
      e.preventDefault(); smartSearch(term.trim());
    }
  });

  // Global keyboard shortcuts (⌘ on Mac, Ctrl elsewhere)
  document.addEventListener("keydown", (e) => {
    const mod = e.metaKey || e.ctrlKey;
    if (!mod) return;
    const k = e.key.toLowerCase();
    const editing = document.querySelector(".card.editing");
    if (k === "k") {                       // Search
      e.preventDefault(); q.focus(); q.select();
    } else if (k === "s") {                // Save
      e.preventDefault();
      if (editing) editing.querySelector('[data-act="save"]').click(); else add();
    } else if (e.key === "Enter") {        // New note / commit
      e.preventDefault();
      if (editing) editing.querySelector('[data-act="save"]').click();
      else if ($("c-body").value.trim()) add();
      else $("c-body").focus();
    }
  });

  const foot = $("foot");
  foot.innerHTML = '<span class="dotstat"></span>' + (AI_ENABLED ? "AI features enabled" : "AI features disabled");
  if (!AI_ENABLED) foot.classList.add("off");

  load();
</script>
</body>
</html>
